import{_ as t,c as d,o,ah as a}from"./chunks/framework.BaqsfJuc.js";const m=JSON.parse('{"title":"ADR 002: Naming Matrix for Protocol Types","description":"","frontmatter":{},"headers":[],"relativePath":"adr/002-naming-matrix.md","filePath":"adr/002-naming-matrix.md","lastUpdated":1763931869000}'),r={name:"adr/002-naming-matrix.md"};function c(i,e,n,s,l,p){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="adr-002-naming-matrix-for-protocol-types" tabindex="-1">ADR 002: Naming Matrix for Protocol Types <a class="header-anchor" href="#adr-002-naming-matrix-for-protocol-types" aria-label="Permalink to “ADR 002: Naming Matrix for Protocol Types”">​</a></h1><ul><li><strong>Date</strong>: 2025-11-22</li><li><strong>Status</strong>: Accepted</li><li><strong>Tags</strong>: protocol, transport, runtime</li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><ul><li>Names for ids, timestamps, frame kinds, and wire keys have drifted across packages, which makes interop harder and confuses new contributors.</li><li>We need a single source of truth that pins type names, property names, and wire-level keys, including how higher-level SDK concepts map onto protocol frames.</li><li>The matrix should be concise enough to live near specs and code but explicit enough to guide future changes and AI-assisted edits.</li></ul><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><ul><li>Canonicalize on <strong>Peer</strong> as the intrinsic identity, using <code>PeerId</code> for type names and <code>peerId</code> for properties.</li><li>Adopt the following naming matrix as the canonical reference for protocol-level types, wire keys, and SDK-facing naming.</li><li>Wire keys (<code>t</code>, <code>id</code>, <code>peerId</code>, <code>caps</code>, <code>s</code>, <code>b</code>) are internal to encode/decode; public TypeScript types expose descriptive names.</li><li>Use these names in code, docs, tests, and public APIs; deviations require an ADR update.</li></ul><p><strong>Rationale</strong>: <code>PeerId</code> avoids collision with Node.js ecosystem terminology and aligns with modern P2P standards (libp2p, IPFS, WebRTC). <code>NodeId</code> created semantic ambiguity in browser contexts and confused process identity with network-visible peer identity.</p><h3 id="_1-identity-timestamps-correlation" tabindex="-1">1. Identity, timestamps, correlation <a class="header-anchor" href="#_1-identity-timestamps-correlation" aria-label="Permalink to “1. Identity, timestamps, correlation”">​</a></h3><table tabindex="0"><thead><tr><th>Domain concept</th><th>Type / Enum name</th><th>Field / Property</th><th>Wire key</th><th>Notes / invariants</th></tr></thead><tbody><tr><td>Peer identity</td><td><code>PeerId</code></td><td><code>peerId</code></td><td><code>peerId</code></td><td>Stable identity of a peer node; survives reconnects</td></tr><tr><td>Connection identity</td><td><code>ConnectionId</code></td><td><code>connectionId</code></td><td>-</td><td>Transient transport link identity; new per TCP/WebSocket</td></tr><tr><td>Session identity</td><td><code>SessionId</code></td><td><code>sessionId</code></td><td>-</td><td>Optional higher-level session across reconnects</td></tr><tr><td>Frame identity</td><td><code>FrameId</code></td><td><code>frameId</code></td><td><code>id</code></td><td>16 opaque bytes; identifies this frame instance on wire</td></tr><tr><td>Correlation identity</td><td><code>CorrelationId</code></td><td><code>correlationId</code></td><td>-</td><td><strong>Reserved for v2.</strong></td></tr><tr><td>Trace identity (req)</td><td><code>TraceId</code></td><td><code>traceId</code></td><td>-</td><td>Optional, spans multi-frame flows</td></tr></tbody></table><blockquote><p><code>frameId</code> — In v1, used for request/response correlation and ACK linkage. Always present on every frame (16 bytes, binary); auto-generated at construction to eliminate defensive checks in runtime/RPC layers. <code>correlationId</code> — Reserved for v2 when explicit tracing or multi-hop flows require separate correlation semantics. Helper: <code>generateFrameId()</code> creates a 128-bit (16 bytes) FrameId via <code>crypto.getRandomValues()</code>. Human-readable representation (for logs/JSON) uses <code>frameIdToHex()</code> → lowercase hex (32 chars).</p></blockquote><h3 id="_2-frames-and-variants" tabindex="-1">2. Frames and variants <a class="header-anchor" href="#_2-frames-and-variants" aria-label="Permalink to “2. Frames and variants”">​</a></h3><table tabindex="0"><thead><tr><th>Domain concept</th><th>Type / Enum name</th><th>Field / Property</th><th>Wire key</th><th>Notes</th></tr></thead><tbody><tr><td>Frame discriminant</td><td><code>FrameKind</code></td><td><code>kind</code></td><td><code>t</code></td><td>Enum: <code>Control</code>, <code>Message</code>, <code>Ack</code>, <code>Error</code></td></tr><tr><td>Base frame</td><td><code>Frame</code></td><td>-</td><td>-</td><td>Union of all frame variants</td></tr><tr><td>Control frame</td><td><code>ControlFrame</code></td><td><code>kind: FrameKind.Control</code></td><td><code>t=0</code></td><td>Handshake / Ping / Pong / Close</td></tr><tr><td>Message frame</td><td><code>MessageFrame</code></td><td><code>kind: FrameKind.Message</code></td><td><code>t=1</code></td><td>Carries routable application data (RPC + pub/sub)¹</td></tr><tr><td>Ack frame</td><td><code>AckFrame</code></td><td><code>kind: FrameKind.Ack</code>; <code>ackFrameId</code></td><td><code>t=2</code></td><td>Acknowledges another frame²</td></tr><tr><td>Error frame</td><td><code>ErrorFrame</code></td><td><code>kind: FrameKind.Error</code></td><td><code>t=3</code></td><td>Represents protocol or app errors</td></tr></tbody></table><blockquote><ol><li>Message frames carry routable application data (RPC + pub/sub). Do not confuse with <code>AppMessage</code> (SDK type), which wraps decoded payloads.</li><li><code>ackFrameId</code> references the target&#39;s <code>frameId</code>.</li></ol></blockquote><h3 id="_3-control-operations-and-payloads" tabindex="-1">3. Control operations and payloads <a class="header-anchor" href="#_3-control-operations-and-payloads" aria-label="Permalink to “3. Control operations and payloads”">​</a></h3><table tabindex="0"><thead><tr><th>Domain concept</th><th>Type / Enum name</th><th>Field / Property</th><th>Wire key</th><th>Notes</th></tr></thead><tbody><tr><td>Control op</td><td><code>ControlOp</code></td><td><code>op</code></td><td><code>c</code></td><td><code>Handshake</code>, <code>Ping</code>, <code>Pong</code>, <code>Close</code></td></tr><tr><td>Control data</td><td>-</td><td><code>data</code></td><td>-</td><td>Optional opaque binary</td></tr><tr><td>Handshake payload</td><td><code>HandshakePayload</code></td><td>-</td><td>-</td><td>Contains <code>peerId</code>, <code>capabilities</code>, <code>metadata</code></td></tr></tbody></table><blockquote><p><code>c</code> is scoped to <code>ControlFrame</code> payloads only; never used in other frame types. <code>data</code> is an optional binary blob used for control frame metadata or handshake extensions.</p></blockquote><h3 id="_4-wire-message-vs-application-message" tabindex="-1">4. Wire message vs application message <a class="header-anchor" href="#_4-wire-message-vs-application-message" aria-label="Permalink to “4. Wire message vs application message”">​</a></h3><table tabindex="0"><thead><tr><th>Domain concept</th><th>Type / Enum name</th><th>Field / Property</th><th>Wire key</th><th>Notes</th></tr></thead><tbody><tr><td>Routing key</td><td><code>Subject</code></td><td><code>subject</code></td><td><code>s</code></td><td>UTF-8 string; see subject namespace rules below</td></tr><tr><td>Raw message bytes</td><td>-</td><td><code>data</code></td><td><code>b</code></td><td><code>Uint8Array</code>; wire is opaque bytes</td></tr><tr><td>Wire message (frame)</td><td><code>MessageFrame</code></td><td><code>subject</code>, <code>data</code></td><td><code>t=1</code></td><td>Routable, identity-bearing unit on the wire</td></tr><tr><td>App-level message (SDK)</td><td><code>AppMessage</code></td><td><code>subject</code>, <code>data</code></td><td>-</td><td>High-level concept in <code>@sideband/peer</code></td></tr></tbody></table><p><strong>Subject namespace rules</strong> (see ADR-006 for full RPC envelope spec):</p><table tabindex="0"><thead><tr><th>Prefix</th><th>Purpose</th><th>Example</th><th>Semantics</th></tr></thead><tbody><tr><td><code>rpc/</code></td><td>RPC request/response</td><td><code>rpc/getUser</code></td><td>Request/Response</td></tr><tr><td><code>event/</code></td><td>Fire-and-forget pub/sub event</td><td><code>event/user.joined</code></td><td>Notification</td></tr><tr><td><code>stream/</code></td><td>Streaming (reserved for v2)</td><td><code>stream/abc123/chunk</code></td><td>(future)</td></tr><tr><td><code>app/</code></td><td>Vendor-specific / custom</td><td><code>app/com.example/mydata</code></td><td>Custom</td></tr></tbody></table><h3 id="_5-errors" tabindex="-1">5. Errors <a class="header-anchor" href="#_5-errors" aria-label="Permalink to “5. Errors”">​</a></h3><table tabindex="0"><thead><tr><th>Domain concept</th><th>Type / Enum name</th><th>Field / Property</th><th>Wire key</th><th>Notes</th></tr></thead><tbody><tr><td>Protocol error code</td><td><code>ProtocolErrorCode</code></td><td><code>code</code></td><td>-</td><td>Enum, low range (e.g. 1000-1999)</td></tr><tr><td>Application error code (optional)</td><td><code>ApplicationErrorCode</code></td><td><code>code</code></td><td>-</td><td>App-defined, high range (e.g. 2000+)</td></tr><tr><td>Error frame details</td><td><code>ErrorFrame</code></td><td><code>message</code>, <code>details</code></td><td>-</td><td>Optional <code>details</code> (binary); see note below.</td></tr></tbody></table><blockquote><p><code>details</code> is an optional binary/structured payload (e.g. JSON, CBOR) carried alongside the error message.</p></blockquote><h3 id="_6-capabilities-and-metadata" tabindex="-1">6. Capabilities and metadata <a class="header-anchor" href="#_6-capabilities-and-metadata" aria-label="Permalink to “6. Capabilities and metadata”">​</a></h3><table tabindex="0"><thead><tr><th>Domain concept</th><th>Type / Enum name</th><th>Field / Property</th><th>Wire key</th><th>Notes</th></tr></thead><tbody><tr><td>Capabilities list</td><td>-</td><td><code>capabilities</code></td><td><code>caps</code></td><td><code>string[]</code>, feature flags or protocol extensions</td></tr><tr><td>Peer metadata</td><td>-</td><td><code>metadata</code></td><td>-</td><td><code>Record&lt;string, string&gt;</code> namespaced keys</td></tr></tbody></table><h3 id="_7-transports-and-runtime" tabindex="-1">7. Transports and runtime <a class="header-anchor" href="#_7-transports-and-runtime" aria-label="Permalink to “7. Transports and runtime”">​</a></h3><table tabindex="0"><thead><tr><th>Domain concept</th><th>Package / Type name</th><th>Notes</th></tr></thead><tbody><tr><td>Transport ABI and helpers</td><td><code>@sideband/transport</code></td><td>Shared interfaces, no env-specific logic</td></tr><tr><td>Node.js/Bun transport</td><td><code>@sideband/transport-node</code></td><td>Node.js / Bun WebSocket adapters</td></tr><tr><td>Browser transport</td><td><code>@sideband/transport-browser</code></td><td>Browser / ServiceWorker adapters</td></tr><tr><td>Protocol package</td><td><code>@sideband/protocol</code></td><td><code>Frame</code>, <code>FrameKind</code>, encode/decode</td></tr><tr><td>Runtime engine</td><td><code>@sideband/runtime</code></td><td>Peer lifecycle, routing, subscriptions</td></tr><tr><td>Peer SDK</td><td><code>@sideband/peer</code></td><td>High-level publish/subscribe/RPC API</td></tr></tbody></table><h3 id="_8-rpc-and-pub-sub-higher-level" tabindex="-1">8. RPC and pub/sub (higher level) <a class="header-anchor" href="#_8-rpc-and-pub-sub-higher-level" aria-label="Permalink to “8. RPC and pub/sub (higher level)”">​</a></h3><table tabindex="0"><thead><tr><th>Domain concept</th><th>Type / Enum name</th><th>Field / Property</th><th>Notes</th></tr></thead><tbody><tr><td>RPC envelope (wire format)</td><td><code>RpcEnvelope</code></td><td><code>t</code>, <code>m</code>, <code>p</code>, <code>result</code>, <code>error</code></td><td>Binary structure in <code>MessageFrame.data</code> (ADR-006)</td></tr><tr><td>RPC request envelope</td><td><code>RpcRequest</code></td><td><code>t: &quot;r&quot;</code>, <code>m</code>, <code>p?</code></td><td>Carries method name + params</td></tr><tr><td>RPC response envelope</td><td><code>RpcResponse</code></td><td><code>t: &quot;R&quot;</code>, <code>result?</code>, <code>error?</code></td><td>Success or error payload</td></tr><tr><td>RPC notification envelope</td><td><code>RpcNotification</code></td><td><code>t: &quot;N&quot;</code>, <code>e</code>, <code>d?</code></td><td>Fire-and-forget event</td></tr><tr><td>Message handler kind</td><td><code>HandlerKind</code> (optional)</td><td>-</td><td>For internal routing (RPC, event, broadcast, etc.)</td></tr></tbody></table><h3 id="_9-helper-api-verbs-for-ai-assistants" tabindex="-1">9. Helper API verbs (for AI assistants) <a class="header-anchor" href="#_9-helper-api-verbs-for-ai-assistants" aria-label="Permalink to “9. Helper API verbs (for AI assistants)”">​</a></h3><table tabindex="0"><thead><tr><th>Operation</th><th>Function name</th><th>Notes</th></tr></thead><tbody><tr><td>Generate frame ID</td><td><code>generateFrameId</code></td><td><code>() -&gt; FrameId</code> (16-byte binary)</td></tr><tr><td>Frame ID to hex</td><td><code>frameIdToHex</code></td><td><code>(FrameId) -&gt; string</code> (32-char lowercase)</td></tr><tr><td>Frame ID from hex</td><td><code>frameIdFromHex</code></td><td><code>(string) -&gt; FrameId</code> (validates 32 hex)</td></tr><tr><td>Encode frame to bytes</td><td><code>encodeFrame</code></td><td><code>Frame -&gt; Uint8Array</code></td></tr><tr><td>Decode bytes to frame</td><td><code>decodeFrame</code></td><td><code>ArrayBufferView -&gt; Frame</code></td></tr><tr><td>Create message frame</td><td><code>createMessageFrame</code></td><td><code>(subject, data, opts) -&gt; MessageFrame</code></td></tr><tr><td>Create ack frame</td><td><code>createAckFrame</code></td><td><code>(frameId, opts) -&gt; AckFrame</code></td></tr><tr><td>Create error frame</td><td><code>createErrorFrame</code></td><td><code>(code, message, opts) -&gt; ErrorFrame</code></td></tr><tr><td>Create handshake frame</td><td><code>createHandshakeFrame</code></td><td><code>(HandshakePayload, opts) -&gt; ControlFrame</code></td></tr></tbody></table><h3 id="ai-usage-hints-suitable-as-code-comments" tabindex="-1">AI usage hints (suitable as code comments) <a class="header-anchor" href="#ai-usage-hints-suitable-as-code-comments" aria-label="Permalink to “AI usage hints (suitable as code comments)”">​</a></h3><blockquote><ul><li>Use <code>Frame</code> / <code>FrameKind</code> / <code>kind</code> for protocol-level variants.</li><li>Use <code>AppMessage</code> for application/pubsub semantics.</li><li>Use <code>peerId</code> for stable peer identity; <code>connectionId</code> is per link, <code>sessionId</code> spans reconnects.</li><li>Use <code>frameId</code> to identify frames; <code>correlationId</code> (or <code>traceId</code>) to link frames.</li><li>Map wire fields (<code>t</code>, <code>id</code>, <code>peerId</code>, <code>caps</code>, <code>s</code>, <code>b</code>) only inside encode/decode; never expose them in public TS types.</li></ul></blockquote><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>All packages align on shared names and wire keys with <strong>PeerId</strong> as the intrinsic identity, reducing ambiguity in docs, code, and AI-assisted edits.</li><li>Eliminates naming collision with Node.js ecosystem and aligns with libp2p/IPFS/WebRTC conventions.</li><li>Every frame has a <code>frameId</code> created by <code>generateFrameId()</code> at construction. This eliminates defensive <code>frameId === undefined</code> checks throughout runtime and RPC layers, improving code clarity and reducing bugs.</li><li>Future additions (new frame kinds, error codes, capability keys) must extend this matrix and update the ADR.</li><li>Tests and examples should assert the public property names while keeping wire keys scoped to codecs.</li><li>Adding <code>connectionId</code>/<code>sessionId</code> is optional but recommended when distinguishing links or resumable sessions; codecs should keep those out-of-band unless explicitly encoded.</li></ul>',35)])])}const b=t(r,[["render",c]]);export{m as __pageData,b as default};
